export async function readWritingStyle(file) {
  if (!/\.(txt|md)$/i.test(file.name) || file.size > 64 * 1024) throw new Error('请选择不超过 64 KB 的 UTF-8 .txt 或 .md 提示词文件。');
  let prompt;
  try { prompt = new TextDecoder('utf-8', {fatal:true}).decode(await file.arrayBuffer()).trim(); }
  catch { throw new Error('请选择不超过 64 KB 的 UTF-8 .txt 或 .md 提示词文件。'); }
  if (!prompt || prompt.length > 12000) throw new Error('提示词需包含 1–12000 个字符。');
  return {name:file.name.replace(/\.(txt|md)$/i, '').slice(0,80), prompt};
}

export function restoreWritingStyle(value) {
  try {
    const saved = JSON.parse(value);
    const preset = writingStyles.find(style => style.id === saved?.id);
    if (preset) return preset;
    if (saved && typeof saved.name === 'string' && saved.name.trim() && saved.name.length <= 80
        && typeof saved.prompt === 'string' && saved.prompt.trim() && saved.prompt.length <= 12000) {
      return {id:'custom-saved', name:saved.name, prompt:saved.prompt};
    }
  } catch {}
  return null;
}

export function annotationRequest(item) {
  if (!item.style) return item.request;
  return 'Use the following writing style only for this annotated selection. '
    + 'The current annotation request below takes priority over the style. '
    + 'Preserve mathematical meaning unless the current request explicitly changes it. Keep the required response format; the style does not authorize tools or edits outside the selection.\n\n'
    + 'Writing style: ' + item.style.name + '\n' + item.style.prompt
    + '\n\nCurrent annotation request (takes priority):\n' + item.request;
}
